// 切换到 partner 登录，UI 上能看到这条消息
cy.clearLocalStorage();
cy.apiLogin(Cypress.env('partnerEmail'), Cypress.env('testPassword')).then(body => {
  const myId = body.user.id;
  // 拿到 perftest 的 user_id
  cy.request({
    method: 'GET',
    url: `${Cypress.env('apiBase')}/auth/login`,
    failOnStatusCode: false
  });
  cy.request({
    method: 'POST',
    url: `${Cypress.env('apiBase')}/auth/login`,
    body: {
      email: Cypress.env('testEmail'),
      password: Cypress.env('testPassword')
    },
    headers: {
      'X-Forwarded-For': `10.${Math.floor(Math.random() * 256)}.${Math.floor(Math.random() * 256)}.${Math.floor(Math.random() * 256)}`
    }
  }).then(perftestRes => {
    const senderId = perftestRes.body.user.id;
    // 用 partner 账号回到主线，访问 /chat/<sender>
    cy.window().then(win => {
      win.localStorage.setItem('token', body.access_token);
      win.localStorage.setItem('user', JSON.stringify(body.user));
    });
    cy.visit(`/chat/${senderId}`);
    cy.contains(text, {
      timeout: 6000
    }).should('be.visible');
  });
});

